package Hello_world;
/*
 * write a java code to print pattern 12345
									 12345
									 12345
									 12345
									 12345

 */
public class A004_pattern3 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n=5;
		for (int i = 1; i <=n; i++) {
			for (int j = 1; j <=n; j++) {
				
				System.out.print(j);
				
			}
			System.out.println();
			
		}

	}

}
